template <typename MaybeConstUserType>
struct Serializer<::crosapi::mojom::AccessTokenResultDataView, MaybeConstUserType> {
  using UserType = typename std::remove_const<MaybeConstUserType>::type;
  using Traits = UnionTraits<::crosapi::mojom::AccessTokenResultDataView, UserType>;

  static void Serialize(MaybeConstUserType& input,
                        MessageFragment<::crosapi::mojom::internal::AccessTokenResult_Data>& fragment,
                        bool inlined) {
    if (CallIsNullIfExists<Traits>(input)) {
       if (inlined)
        fragment->set_null();
      return;
    }

    if (!inlined)
      fragment.Allocate();

    // TODO(azani): Handle unknown and objects.
    // Set the not-null flag.
    fragment->size = kUnionDataSize;
    fragment->tag = Traits::GetTag(input);
    switch (fragment->tag) {
      case ::crosapi::mojom::AccessTokenResultDataView::Tag::kAccessTokenInfo: {
        decltype(Traits::access_token_info(input))
            in_access_token_info = Traits::access_token_info(input);
        mojo::internal::MessageFragment<
            typename decltype(fragment->data.f_access_token_info)::BaseType>
            value_fragment(fragment.message());
        mojo::internal::Serialize<::crosapi::mojom::AccessTokenInfoDataView>(
            in_access_token_info, value_fragment);
        MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
            value_fragment.is_null(),
            mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
            "null access_token_info in AccessTokenResult union");
        fragment->data.f_access_token_info.Set(
            value_fragment.is_null() ? nullptr : value_fragment.data());
        break;
      }
      case ::crosapi::mojom::AccessTokenResultDataView::Tag::kError: {
        decltype(Traits::error(input))
            in_error = Traits::error(input);
        mojo::internal::MessageFragment<
            typename decltype(fragment->data.f_error)::BaseType>
            value_fragment(fragment.message());
        mojo::internal::Serialize<::crosapi::mojom::GoogleServiceAuthErrorDataView>(
            in_error, value_fragment);
        MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
            value_fragment.is_null(),
            mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
            "null error in AccessTokenResult union");
        fragment->data.f_error.Set(
            value_fragment.is_null() ? nullptr : value_fragment.data());
        break;
      }
    }
  }

  static bool Deserialize(::crosapi::mojom::internal::AccessTokenResult_Data* input,
                          UserType* output,
                          Message* message) {
    if (!input || input->is_null())
      return CallSetToNullIfExists<Traits>(output);

    ::crosapi::mojom::AccessTokenResultDataView data_view(input, message);
    return Traits::Read(data_view, output);
  }
};

