inline void AccountKeyDataView::GetIdDataView(
    mojo::StringDataView* output) {
  auto pointer = data_->id.Get();
  *output = mojo::StringDataView(pointer, message_);
}


inline void AccountDataView::GetKeyDataView(
    AccountKeyDataView* output) {
  auto pointer = data_->key.Get();
  *output = AccountKeyDataView(pointer, message_);
}
inline void AccountDataView::GetRawEmailDataView(
    mojo::StringDataView* output) {
  auto pointer = data_->raw_email.Get();
  *output = mojo::StringDataView(pointer, message_);
}


inline void GoogleServiceAuthErrorDataView::GetErrorMessageDataView(
    mojo::StringDataView* output) {
  auto pointer = data_->error_message.Get();
  *output = mojo::StringDataView(pointer, message_);
}
inline void GoogleServiceAuthErrorDataView::GetTokenBindingChallengeDataView(
    mojo::StringDataView* output) {
  auto pointer = data_->header_.version >= 14
                 ? data_->token_binding_challenge.Get() : nullptr;
  *output = mojo::StringDataView(pointer, message_);
}




inline void AccountUpsertionResultDataView::GetAccountDataView(
    AccountDataView* output) {
  auto pointer = data_->account.Get();
  *output = AccountDataView(pointer, message_);
}
